import java.awt.*;public class Goal{	private final int MASK = 50;	private int my_x, my_y;	public Goal(int this_x, int this_y){			my_x = this_x;		my_y = this_y;		}	public void draw(Graphics page){				page.setColor (Color.red);		page.fillRect(my_x, my_y, MASK, MASK);		page.setColor(Color.black);		page.drawString("Goal", my_x, my_y);	}	public boolean goalFound(int your_x, int your_y){			int mask_x = your_x + Robot.MASK;		int mask_y = your_y + Robot.MASK;		boolean found_goal = false;				if (mask_x >= my_x)			if (mask_x <= my_x + MASK)				if (mask_y >= my_y - MASK)					if (mask_y <= my_y)						found_goal = true;		return found_goal;		}}